IF OBJECT_ID('dbo.account_transaction','U') IS NOT NULL DROP TABLE dbo.account_transaction; IF OBJECT_ID('dbo.account_tx_audit','U') IS NOT NULL DROP TABLE dbo.account_tx_audit; IF OBJECT_ID('dbo.accounts','U') IS NOT NULL DROP TABLE dbo.accounts; CREATE TABLE dbo.accounts(AccountID int PRIMARY KEY,AccountName nvarchar(100),AccountType varchar(20),Balance decimal(12,2)); CREATE TABLE dbo.account_transaction(TransactionID int IDENTITY PRIMARY KEY,AccountID int REFERENCES dbo.accounts,Amount decimal(12,2),TransactionType varchar(10),TransactionDate datetime2 DEFAULT SYSDATETIME()); CREATE TABLE dbo.account_tx_audit(AuditID int IDENTITY PRIMARY KEY,TransactionID int,ActionName varchar(10),AccountID int,Amount decimal(12,2),TransactionType varchar(10),ChangedBy sysname,ChangedAt datetime2 DEFAULT SYSDATETIME()); INSERT dbo.accounts VALUES(1,'Anu','Savings',10000),(2,'Bala','Savings',5000),(3,'Chitra','Savings',8000),(4,'Devi','Savings',2500),(5,'Ethan','Savings',6000);